<script setup lang="ts">
import {Play,Repeat,Shuffle,SquareCheck,Star,Share2,Download,Pencil,Eye,EyeOff,ListPlus,GalleryVerticalEnd,Trash2,RefreshCw,House,Move,Image,ListFilter} from 'lucide-vue-next'
const icons:Record<string,any>={play:Play,loop:Repeat,shuffle:Shuffle,select:SquareCheck,rating:Star,share:Share2,download:Download,metadata:Pencil,watched:Eye,unwatched:EyeOff,continue:Play,playlist:ListPlus,series:GalleryVerticalEnd,delete:Trash2,refresh:RefreshCw,favorite:Star,home:House,remove:House,renameFavorite:Pencil,cover:Image,renameCollection:Pencil,deleteCollection:Trash2,reorder:Move,reorderMember:Move,removeMember:Trash2,favoriteTitle:ListFilter,favoriteOrder:Move,hideFavorites:House,renameFavorites:Pencil,nextSort:ListFilter}
import {nextTick,onMounted,onUnmounted,ref} from 'vue'
import type {MenuEntry} from './workspaceMenus'
const props=defineProps<{x:number;y:number;entries:MenuEntry[];label:string}>()
const emit=defineEmits<{action:[id:string];close:[]}>()
const panel=ref<HTMLElement>(),left=ref(props.x),top=ref(props.y)
let previous:HTMLElement|null=null
function key(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();emit('close');return}const buttons=[...panel.value!.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')];const index=buttons.indexOf(document.activeElement as HTMLButtonElement);if(['ArrowDown','ArrowUp','Home','End','Tab'].includes(event.key)){event.preventDefault();buttons[event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowUp'||event.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus()}}
onMounted(async()=>{previous=document.activeElement as HTMLElement;await nextTick();const rect=panel.value!.getBoundingClientRect();left.value=Math.max(8,Math.min(props.x,window.innerWidth-rect.width-8));top.value=Math.max(8,Math.min(props.y,window.innerHeight-rect.height-8));panel.value?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus()})
onUnmounted(()=>previous?.isConnected&&previous.focus())
</script>
<template><Teleport to="body"><div class="workspace-menu-dismiss" @pointerdown.self="emit('close')" @contextmenu.prevent.self="emit('close')" @keydown="key"><div ref="panel" class="workspace-context" role="menu" :aria-label="label" :style="{left:left+'px',top:top+'px'}"><button v-for="entry in entries" :key="entry.id" role="menuitem" :disabled="entry.disabled" :title="entry.reason" @click="emit('action',entry.id)"><component v-if="icons[entry.id]" :is="icons[entry.id]" :size="16" aria-hidden="true"/><span>{{entry.label}}</span></button></div></div></Teleport></template>
<style scoped>.workspace-menu-dismiss{position:fixed;inset:0;z-index:500}.workspace-context{position:fixed;min-width:220px;max-height:calc(100vh - 16px);overflow:auto;background:var(--background);color:var(--foreground);border:1px solid var(--border);border-radius:12px;padding:6px;box-shadow:0 12px 40px #0005}.workspace-context button{display:flex;align-items:center;gap:10px;text-align:left;padding:9px 14px;width:100%;border-radius:6px}.workspace-context button:hover,.workspace-context button:focus-visible{background:var(--secondary)}button:disabled{opacity:.4}</style>
